CREATE TABLE `planning_product` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `organization_code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `code` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `class_code` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `uom_id` bigint NOT NULL,
  `secondary_uom_id` bigint DEFAULT NULL,
  `secondary_per_unit` decimal(18,6) DEFAULT NULL COMMENT 'amount of the second unit per one stock unit',
  `secondary_per_unit_min` decimal(18,6) DEFAULT NULL COMMENT 'amount of the second unit per one stock unit',
  `secondary_per_unit_max` decimal(18,6) DEFAULT NULL COMMENT 'amount of the second unit per one stock unit',
  `volume_per_unit` decimal(18,6) DEFAULT NULL COMMENT 'volume one stock unit takes up, in volume_uom_id',
  `volume_uom_id` bigint DEFAULT NULL,
  `catch_weight` bit(1) NOT NULL DEFAULT b'0' COMMENT 'traded by the actual amount of the second unit (D-159)',
  `shelf_life_days` int DEFAULT NULL,
  `expires` bit(1) NOT NULL DEFAULT b'1' COMMENT 'off: the product does not perish; on without days: a shelf life not stated (D-159)',
  `temperature_class` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sourcing_preference` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sex` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `genetic_line_id` bigint DEFAULT NULL,
  `graded_from_id` bigint DEFAULT NULL,
  `consumption_backward_days` int DEFAULT NULL,
  `consumption_forward_days` int DEFAULT NULL,
  `salvage_value_per_unit` decimal(18,6) DEFAULT NULL COMMENT 'what a unit of expired stock still fetches; 0 is stated worth nothing, null is not stated',
  `salvage_currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'stated exactly when salvage_value_per_unit is',
  `disposal_cost_per_unit` decimal(18,6) DEFAULT NULL COMMENT 'what discarding a unit of expired stock costs; 0 is stated free, null is not stated',
  `disposal_currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'stated exactly when disposal_cost_per_unit is',
  `status` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'PROPOSED (a planner''s addition, out of the plan), ACTIVE or INACTIVE',
  `created_date` datetime(6) NOT NULL,
  `created_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `last_modified_date` datetime(6) NOT NULL,
  `last_modified_by` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `carrying_value_amount` decimal(18,6) DEFAULT NULL COMMENT 'the books unit cost per carrying_value_pricing_quantity of the basis',
  `carrying_value_currency` varchar(3) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `carrying_value_basis` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'PER_UNIT or PER_KG',
  `carrying_value_pricing_quantity` decimal(18,6) DEFAULT NULL,
  `carrying_value_valued_on` date DEFAULT NULL COMMENT 'the day of the source latest entry the valuation comes from',
  `carrying_value_data_origin` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `budget_line_id` bigint DEFAULT NULL COMMENT 'the budget line the product is budgeted under; null leaves it out of the budget compare',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_planning_product_organization_code` (`organization_code`,`code`),
  KEY `fk_planning_product_genetic_line` (`genetic_line_id`),
  KEY `fk_planning_product_graded_from` (`graded_from_id`),
  KEY `fk_planning_product_uom` (`uom_id`),
  KEY `fk_planning_product_secondary_uom` (`secondary_uom_id`),
  KEY `fk_planning_product_volume_uom` (`volume_uom_id`),
  KEY `fk_planning_product_budget_line` (`budget_line_id`),
  CONSTRAINT `fk_planning_product_budget_line` FOREIGN KEY (`budget_line_id`) REFERENCES `budget_line` (`id`),
  CONSTRAINT `fk_planning_product_genetic_line` FOREIGN KEY (`genetic_line_id`) REFERENCES `genetic_line` (`id`),
  CONSTRAINT `fk_planning_product_graded_from` FOREIGN KEY (`graded_from_id`) REFERENCES `planning_product` (`id`),
  CONSTRAINT `fk_planning_product_organization` FOREIGN KEY (`organization_code`) REFERENCES `organization` (`code`),
  CONSTRAINT `fk_planning_product_secondary_uom` FOREIGN KEY (`secondary_uom_id`) REFERENCES `uom` (`id`),
  CONSTRAINT `fk_planning_product_uom` FOREIGN KEY (`uom_id`) REFERENCES `uom` (`id`),
  CONSTRAINT `fk_planning_product_volume_uom` FOREIGN KEY (`volume_uom_id`) REFERENCES `uom` (`id`),
  CONSTRAINT `ck_planning_product_amount_currency` CHECK ((((`salvage_value_per_unit` is null) = (`salvage_currency` is null)) and ((`disposal_cost_per_unit` is null) = (`disposal_currency` is null)))),
  CONSTRAINT `ck_planning_product_carrying_value` CHECK ((((`carrying_value_amount` is null) = (`carrying_value_currency` is null)) and ((`carrying_value_amount` is null) = (`carrying_value_basis` is null)) and ((`carrying_value_amount` is null) = (`carrying_value_pricing_quantity` is null)) and ((`carrying_value_amount` is null) = (`carrying_value_data_origin` is null)) and ((`carrying_value_valued_on` is null) or (`carrying_value_amount` is not null)))),
  CONSTRAINT `ck_planning_product_carrying_value_amounts` CHECK ((((`carrying_value_amount` is null) or (`carrying_value_amount` >= 0)) and ((`carrying_value_pricing_quantity` is null) or (`carrying_value_pricing_quantity` > 0)) and ((`carrying_value_basis` is null) or (`carrying_value_basis` in (_utf8mb4'PER_UNIT',_utf8mb4'PER_KG'))))),
  CONSTRAINT `ck_planning_product_class_by_category` CHECK (((`category` = _utf8mb4'CONSUMABLE') = (`class_code` is not null))),
  CONSTRAINT `ck_planning_product_consumption_window` CHECK ((((`consumption_backward_days` is null) = (`consumption_forward_days` is null)) and ((`consumption_backward_days` is null) or (`consumption_backward_days` >= 0)) and ((`consumption_forward_days` is null) or (`consumption_forward_days` >= 0)))),
  CONSTRAINT `ck_planning_product_genetic_line_by_category` CHECK (((`genetic_line_id` is null) or (`category` = _utf8mb4'BIOLOGICAL_ASSET'))),
  CONSTRAINT `ck_planning_product_positive` CHECK ((((`shelf_life_days` is null) or (`shelf_life_days` >= 0)) and ((`salvage_value_per_unit` is null) or (`salvage_value_per_unit` >= 0)) and ((`disposal_cost_per_unit` is null) or (`disposal_cost_per_unit` >= 0)) and ((`secondary_per_unit` is null) or (`secondary_per_unit` > 0)) and ((`secondary_per_unit_min` is null) or (`secondary_per_unit_min` > 0)) and ((`secondary_per_unit_max` is null) or (`secondary_per_unit_max` > 0)) and ((`volume_per_unit` is null) or (`volume_per_unit` > 0)))),
  CONSTRAINT `ck_planning_product_second_unit` CHECK ((((`secondary_uom_id` is null) = (`secondary_per_unit` is null)) and ((`secondary_per_unit` is not null) or ((`secondary_per_unit_min` is null) and (`secondary_per_unit_max` is null))) and ((`secondary_per_unit_min` is null) or (`secondary_per_unit_min` <= `secondary_per_unit`)) and ((`secondary_per_unit_max` is null) or (`secondary_per_unit` <= `secondary_per_unit_max`)) and ((`catch_weight` = 0) or (`secondary_uom_id` is not null)) and ((`secondary_uom_id` is null) or (`secondary_uom_id` <> `uom_id`)))),
  CONSTRAINT `ck_planning_product_sex_by_category` CHECK (((`sex` is null) or (`category` in (_utf8mb4'BIOLOGICAL_ASSET',_utf8mb4'BIOLOGICAL_OUTPUT')))),
  CONSTRAINT `ck_planning_product_shelf_life` CHECK (((`expires` = 1) or (`shelf_life_days` is null))),
  CONSTRAINT `ck_planning_product_shelf_life_by_category` CHECK (((`shelf_life_days` is null) or (`category` <> _utf8mb4'BIOLOGICAL_ASSET'))),
  CONSTRAINT `ck_planning_product_status` CHECK ((`status` in (_utf8mb4'PROPOSED',_utf8mb4'ACTIVE',_utf8mb4'INACTIVE'))),
  CONSTRAINT `ck_planning_product_temperature_by_category` CHECK (((`category` = _utf8mb4'BIOLOGICAL_ASSET') = (`temperature_class` is null))),
  CONSTRAINT `ck_planning_product_volume` CHECK (((`volume_per_unit` is null) = (`volume_uom_id` is null)))
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
